// `veyq.openapi` — spec-first generation: Kotlin models + JAX-RS (Quarkus) interfaces from the contracts, one spec set
// per owner (ADR 0079), each generated by the Gradle project that owns it. The owner is the project's path and the
// specs' directory (`:core` → `contracts/api/`, `:apps:<application>` → `contracts/api/<application>/`); a project opts in once, after
// applying the plugin: `veyqOpenApi { generateOwnSpecs() }` (`me.raddatz.veyq.buildlogic.VeyqOpenApiExtension`; the sets
// are `me.raddatz.veyq.buildlogic.SpecSets`).
plugins {
    id("org.jetbrains.kotlin.jvm")
}

extensions.create<me.raddatz.veyq.buildlogic.VeyqOpenApiExtension>("veyqOpenApi", project)
